	title 'QD INIT              GS ROM 3.0'*****************************************************************			   **              Init			   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1989	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   *****************************************************************	include 'all.macros'	INCLUDE ':QDEquates:core.globals1'	INCLUDE ':QDEquates:core.globals2'	INCLUDE ':QDEquates:region.equs'	INCLUDE ':QDEquates:qd.data.asm'		include '::sys.equs.asm'		include 'e16.memory'TheCoreVersion	equ $0300	; real version 3.0	MACRO&lab	PushPtr &addr&lab	dc.B $F4	dc.W (&addr)>>16	dc.B $F4	dc.W &addr	MEND****************************************************************** CoreBootInit** Installs the address of update cursor	in the update* cursor vector of bank E1.*****************************************************************	EXPORT CoreBootInitCoreBootInit	PROC	PushWord #CurUpdateRefNum	; install pointer to update	PushPtr UpdateCursor 	; cursor routine	_SetVector	PushLong #E0Vectors		; copy internal vectors to bank E0	pea $00E0	pea $1E00	PushLong #$1FC		; TheE0VEnd-TheE0VStart	_BlockMove	jmp oEndCall0	ENDP****************************************************************** CoreApInit	(ZPToUse : word;*	 MasterSCB : word;*	 MaxWidth : word;*	 ApID : word);*** Modifications**     April 8, 1986	   I now check for errors correctly after*	   GetTextHandle.**     April 30, 1986   I finally handle	the special case where*	   MaxWidth is a 0 on entry.  Also the clip buffer*	   sizing is now a subroutine that can be called*	   from SetMaxWidth.  This way the buffer can be*	   changed.**     May 2, 1986	   I now do text buffer sizing directly	since*	   it is not automatic in my OpenPort and SetPort**     Dec 23, 1986	   Code clean up and compression.**     2/17/88   GCP	   changed zero loop to clear third zero page**     2/1/89 Mensch	Added Bitflag support for the top byte of the*	MasterSCB flag. These flags can be used to select*	various quickdraw options that we couldn't use before.*****************************************************************	EXPORT CoreApInitCoreApInit	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TheUserID	equ RTL2+3TheMaxWidth	equ TheUserID+2TheMasterSCB	equ TheMaxWidth+2PtrToZP	equ TheMasterSCB+2; New MasterSCB Equates we can useUseShadow	equ $8000HiddenSpeed	equ $4000Avail1	equ $2000Avail2	equ $1000	jsl IncBusyFlg;-----------------------------------------------;; See if the last user has shut down.;	cmp #0	beq continue	ldx #AlreadyInitialized	jmp oBusyErr8;-----------------------------------------------;; Set up my entry in WAPcontinue		; 	phd	; save direct	lda PtrToZP,s	PushWord #0	; Not a user call	PushWord #TSNumber	; Put TSNum on stack	PushWord #0	; High word is zero	pha	; low word is in a	_SetWAP;-----------------------------------------------;; Move important values to zero page	lda PtrToZP,s	; initialize some stuff	tcd;-------------------------------------------------;; But first initialize it to zero.  (This is; important for handles so that those not allocated; in an errant attempt to startup are not disposed; of illegally!;	ldx #0ZeroLoop	stz 0,x	inx	inx	cpx #768	bcc ZeroLoop	lda TheMaxWidth,s	; zero is special number that I fix	cmp #0	bne UseThisOne	lda #160UseThisOne	sta MaxWidth	lda TheMasterSCB,s	sta MasterSCB	lda TheUserID,s	sta UserID;-----------------------------------------------;; reserve the super	hi-res screen so that; no one else will get it.;	pha	; space for handle	pha	PushLong #$8000	; size of screen	pei UserID	PushWord #$C002	; fixed location, locked	pea $00E1	pea $2000	jsl NewHandleGlue	bcc GotScreen	pla	pla	lda #ScreenReserved	jmp CannotInitializeGotScreen		; 	ldx #256	; save this for later	pla	sta ScreenHandle,x	pla	sta ScreenHandle+2,x;; EXP 1/25/89 see if we can allocate the shadowed screen, if so, do it!; EXPERIMENT 1 aprox 10% speed increase	ldx #512	; switch to qd dpage 2	lda MasterSCB	; get the passed flags from the top of MasterSCB	and #$4000	; strip off the high bit 14 ...	beq @NoDirty	lda #$8000@NoDirty	sta <DirtyDPFlags,x	; and save this value...	lda MasterSCB	bpl EXP0020	; if carry clear, no shadowing!		pha	; space for handl	pha	PushLong #$8000	; size of screen	pei UserID	PushWord #$C002	; fixed location, locked	pea $0001	pea $2000	jsl NewHandleGlue	pla	; discard trhis handle for now...	plx	bcs EXP0010	; if an error, then we didn't allocate Shadow screen	; If we get this far, we have allocated a shadowed screen and we should now set; the shadowing bit on for the SHR screen.	sep #$20	; turn off long <A>	longA Off	lda >$E0C035	; load the shadow register	and #$F7	; reset bit 3...	sta >$E0C035	; and resave it!	longA On	REP #$20	; and turn back on long <A>	bra EXP0020EXP0010	; Shadowing didn't get allocated, lets change our bitflags here	lda MasterSCB	and #$7FFF	; strip off the shadow flag	sta MasterSCB	; to indicate we are not using shadowing.EXP0020;; END of Experiment!;-----------------------------------------------;; Turn linearization on	sep #%00100000	; 8 bit a-reg	longa off	lda >NewVideo	ora #$40	; only linearize first	sta >NewVideo	rep #%00100000	; back to 16 bits	longa on;-----------------------------------------------;; Call bennet to initialize the Text Buffer Handle;	jsl GetTextHandle	bcc GotText	jmp CannotInitializeGotText		; ;-----------------------------------------------;; Init the SCB's and color table;; 2/1/89 Mensch; Added new flags on the top of the MasterSCB variable.; Must strip them off before we use them here.	lda MasterSCB	and #$00FF	; strip off QD flags	pha		_SetAllSCBs	pea FirstTable>>16	pea FirstTable**$FFFF	_InitColorTable;-----------------------------------------------;; Init the cursor and clear the screen to; black.	jsl InitCursor	cmp #0	beq DidCursor	jmp CannotInitializeDidCursor		; 	PushWord #0	; clear the screen to black	_ClearScreen;-------------------------------------------------;; Setup  the current system font on zero page.;	ldx #256	lda #SystemFont	sta SysFont,x	lda #^SystemFont	sta SysFont+2,x;-----------------------------------------------;; Get space for the	things we need.	lda #10280	; size of handle	ldx UserID	; userid to use	ldy #$0300	; attributes	jsr SpecialNewHandle	bcc GotCache	jmp CannotInitializeGotCache		; ;low word is in x, high word in y	txa	; need x for indexing	ldx #$02F4	; third zero page of qd	sta 0,x	sty 2,x;-----------------------------------------------------------;; Get the fast font if we can...;; MODIFIED TEMP	import DoFastSetup		tdc	pha	pha	; room for result...	jsl DoFastSetup	pla	ply	bcs @noFastFont	ldx #256	sta SysFont,x	sty SysFont+2,x		ldx #512	sta FastRomFont,x	sty FastRomFont+2,x@NoFastFont;; first the initial	graf port.;	lda #PortSize	; size of handle	ldx UserID	; userid to use	ldy #attrFixed	; attributes	jsr SpecialNewHandle	bcc GotPort	jmp CannotInitializeGotPort		; 	stx Temp	sty Temp+2	txa	ldx #256	sta FirstPortHandle,x ; put a copy of the handle	tya	sta FirstPortHandle+2,x	ldy #2	; deref the handle	lda [Temp],y	pha	lda [Temp]	pha	_OpenPort	; make open port call	bcc PortIsOpen	jmp CannotInitializePortIsOpen		; ;----------------------------------------------------;; We have a port, so now set up the default; text buffer size.;	lda #40	sta NewMaxFontWidth	lda #20	sta NewTBHeight	stz ForcedFont	jsl SetTB	bcc BufIsSized	jmp CannotInitializeBufIsSized		; 	lda MaxWidth	jsr CalcClipSize	ldx UserID	ldy #0	jsr SpecialNewHandle	bcc GotBuffer	jmp CannotInitializeGotBuffer		; 	stx BufferHandle	sty BufferHandle+2	ldx #256	lda #1	sta RandSeed,x	stz RandSeed+2,x	_GrafOn	jmp BusyEC8CannotInitialize		; 	sta UserID	;use this to store error code;-------------------------------------------------;; Now I have to unwind, releasing any memory; I may have successfully obtained before; failing.;	_QDShutdown	ldx UserID	jmp BusyErr8	ENDP****************************************************************** CalcClipSize** We need a memory for the scan line buffers and* three region state records.* It needs to be**    Size = MaxWidth + MaxWidth * 3 * 4	/ 8 +*              3 * StateRecSize*****************************************************************	EXPORT CalcClipSizeCalcClipSize	PROC	pha	; put max width on stack	clc	adc 1,s	adc 1,s	lsr a	clc	adc 1,s	clc	adc #3*StateRecSize	plx	rts	ENDP****************************************************************** CoreTerminate** Releases the memory held for scan line buffers, cursor* save areas, text buffers.** 3/14/89	Mensch* Fixed up terminate to not dispose of the fastfont...****************************************************************	EXPORT CoreTerminateCoreTerminate	PROC	cmp #0	bne Continue	jmp oEndCall0Continue	jsr QDStart	pea #2	; set the purge level to 2	ldx #512	; on the fastfont...	lda FastRomFont+2,x	and #$00FF	pha	lda FastRomFont,x	pha	_SetPurge;	jsl DisposeHandleGlue** Deallocate rgn cache memory*	ldx #$02F4	lda 2,x	pha	lda 0,x	pha	jsl DisposeHandleGlue;-----------------------------------------------;; Close the first port and get rid of the memory; it is in.;	ldx #256	lda FirstPortHandle+2,x	pha	sta temp+2	lda FirstPortHandle,x	pha	sta temp	lda [temp]	tax	ldy #2	lda [temp],y	pha	phx	_ClosePort	jsl DisposeHandleGlue;-----------------------------------------------;; Get rid of text buffer;	PushLong TextBufHandle	jsl DisposeHandleGlue;-----------------------------------------------;; Get rid of the buffer memory	pei BufferHandle+2	pei BufferHandle	jsl DisposeHandleGlue;-----------------------------------------------; Get rid of shadowed ram here; test for shadowing enabled, if it is, turn it off and ; dispose of the screen...	sep #$20	; turn off long <A>	longA Off	lda >$E0C035	; load the shadow register	and #$08	; set bit 3... (turn screen shadow off)	bne @NotShadowed	longA On	REP #$20	; and turn back on long <A>		pha	pha	pea $0001	; find the shadowed screen memory	pea $2000	; handle, shadowing was on...	_FindHandle	_DisposeHandle	; and throw it the hell away..@NotShadowed	longA On	REP #$20;-----------------------------------------------;; Now get rid of screen memory.  Cannot	do a find; since we could be	called after a startup call; that was aborted because screen was already; owned.  We don't want to release someone; else's memory.;	ldx #256	lda ScreenHandle+2,x	pha	lda ScreenHandle,x	pha	jsl DisposeHandleGlue;-----------------------------------------------;; Get rid of the memory used by cursor save;	jsr CursorShutDown;-----------------------------------------------;; Clear the entry in the WAPT;	lda #0	; not a user call (seed the a-reg	pha	; to save bytes below	PushWord #TSNumber	; Put TSNum on stack	pha	; new value is zero	as set above.	pha	_SetWAP;----------------------------------------------------;; Turn off graphics	and linearization in bank 1/E1;	sep #$30	; go to 8 bit mode	longa off	longi off	lda >NewVideo	and #%00111111	; turn off graphics	and linearization	sta >NewVideo	rep #$30	; go back to 16	longi on	longa on;------------------------------------------------------; Turn off shadowing for the SHR Screen;	sep #$20	; turn off long <A>	longA Off	lda >$E0C035	; load the shadow register	ora #$08	; set bit 3... (turn screen shadow off)	sta >$E0C035	; and resave it!	longA On	REP #$20	; and turn back on long <A>		jmp BusyEC0	ENDP****************************************************************** CoreVersion** Returns the version number.*** Change History** 17 Oct 88	Steven Glass** Added call to youve got to be kidding.****************************************************************CoreVersion	PROC EXPORT	import YouveGotToBeKiddingRTL1	equ 1RTL2	equ RTL1+3V	equ RTL2+3	jsl YouveGotToBeKidding	jsl GimmeVersion	sta V,s	jmp oEndCall0	EXPORT iGimmeVersioniGimmeVersion		;       	lda #TheCoreVersion	rtl	ENDP****************************************************************** CoreReset** Called when reset	is pressed.  I try to shutdown.*****************************************************************	EXPORT CoreResetCoreReset	PROC	_QDShutDown	; shutdown everything	jmp oEndCall0	ENDP****************************************************************** QDStatus** Returns TRUE if active, FALSE otherwise.******************************************************************	EXPORT QDStatusQDStatus	PROCRTL1	equ 1RTL2	equ RTL1+3TheResult	equ RTL2+3	cmp #0	beq NotActive	lda #TRUEGotIt	sta TheResult,s	jmp oEndCall0NotActive	lda #False	bra GotIt	ENDP;                COPY init/CORE.DATA	EXPORT CoreDATACoreDATA	PROC	EXPORT Port320Port320		; 	EXPORT StandardPortStandardPort		; 	EXPORT xLocStartxLocStart	DC.W StandardSCB	; PortSCB	DC.L $E12000	; ImageRef	DC.W 160	; Width	DC.W 0,0,200,320	; BoundsRect	EXPORT xLocEndxLocEnd		; 	DC.W 0,0,200,320	; PortRect	DC.L 0	; ClipRef	DC.L 0	; VisRef	DC.B $FF	; BkPat	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	EXPORT StdPnStateStdPnState	DC.W 0,0	; PnLoc	DC.W 1,1	; PnSize	DC.W 0	; PnMode	DC.B 0	; PnPat	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B 0	DC.B $FF	; PnMask	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	DC.B $FF	EXPORT xEndPnStatexEndPnState	DC.W 0	; PnVis	DC.L SystemFont	; FontHandle	DC.L 0	; FontID	DC.W 0	; FontFlags	DC.W 0	; TxSize	DC.W 0	; TxFace	DC.W 0	; TxMode	DC.L 0	; SpaceExtra is a fixed pt value	DC.L 0	; CharExtra is a fixed pt value	DC.W 0	; FGColor	DC.W $FFFF	; BGColor	DC.L 0	; PicSave	DC.L 0	; RgnSave	DC.L 0	; PolySave	DC.L 0	; GrafProcs	DC.W 0	; ArcRot	DC.L 0	; UserField	DC.L 0	; SystemField	EXPORT EndStandardPortEndStandardPort		; 	EXPORT Port640Port640		; 	DC.W StandardSCB+$80 ; MasterSCB	DC.L $E12000	; ImageRef	DC.W 160	; Width	DC.W 0,0,200,640	; BoundsRect	DC.W 0,0,200,640	; PortRect	ENDP	EXPORT ColorDataColorData	PROC	GOTO .table2; This table provides all eight saturated points of a color; cube plus 8 move from the sides of the cube for a rich collection; of colors.  This table was suggested by Mike Potel in ADG.	EXPORT Table320Table320	DC.W $0000	; black	DC.W $0F00	; red	DC.W $00F0	; green	DC.W $000F	; blue	DC.W $0088	; teal	DC.W $0808	;	DC.W $0660	; brown	DC.W $0555	; dark gray	DC.W $0AAA	; light gray	DC.W $0F80	; orange	DC.W $08F8	DC.W $0F88	DC.W $0FF0	; Yellow	DC.W $0F0F	; magneta	DC.W $00FF	; cyan	DC.W $0FFF	; white.table2; This is Annette Wagners subject color	table.  Chosen because; she liked the colors.	EXPORT Table320Table320	DC.W $0000	; black	DC.W $0777	; Dark gray	DC.W $0841	; brown	DC.W $072C	; purple	DC.W $000F	; blue	DC.W $0080	; dark green?	DC.W $0F70	; orange	DC.W $0D00	; red	DC.W $0FA9	; flesh	DC.W $0FF0	; yellow	DC.W $00E0	; green	DC.W $04DF	; light blue	DC.W $0DAF	; light purple or lilac	DC.W $078F	; periwinkle blue	DC.W $0CCC	; light gray	DC.W $0FFF	; white	GOTO .there	EXPORT Table640Table640	DC.W $0000	; black	DC.W $0F00	; red	DC.W $000F	; blue	DC.W $0FFF	; white	DC.W $0000	; black	DC.W $0F00	; red	DC.W $000F	; blue	DC.W $0FFF	; white	DC.W $0000	; black	DC.W $0F00	; red	DC.W $000F	; blue	DC.W $0FFF	; white	DC.W $0000	; black	DC.W $0F00	; red	DC.W $000F	; blue	DC.W $0FFF	; white.there	EXPORT Table640Table640	DC.W $0000	; black	DC.W $0F00	; red	DC.W $00F0	; green	DC.W $0FFF	; white	DC.W $0000	; black	DC.W $000F	; blue	DC.W $0FF0	; yellow	DC.W $0FFF	; white	DC.W $0000	; black	DC.W $0F00	; red	DC.W $00F0	; green	DC.W $0FFF	; white	DC.W $0000	; black	DC.W $000F	; blue	DC.W $0FF0	; yellow	DC.W $0FFF	; white	ENDP	EXPORT QDProcsQDProcs	PROC	EXPORT HereHere		; 	DC.L StdText-1	DC.L StdLine-1	DC.L StdRect-1	DC.L StdRRect-1	DC.L StdOval-1	DC.L StdArc-1	DC.L StdPoly-1	DC.L StdRgn-1	DC.L StdPixels-1	DC.L StdComment-1	DC.L StdTxMeas-1	DC.L StdTxBnds-1	DC.L StdGetPic-1	DC.L StdPutPic-1	ENDP;                copy init/adv.stuff****************************************************************** QDStart** This is a local routine that increments the busy flag, saves* the current direct register on the stack and transfers* the a register to	the D register.** This is meant to be called at the start of any QD entry point* that requires zero page and the busy flag to be incremented.** In Doing this we trash the X-Register.  Hopefully this will* not cause anyone any problems.** We do know that A	and Y must be untouched.  Y for PortWord* and PortLong.  A for cursor routines that add $100 to A** 2/27/89	Mensch and Konstantine** Squeeze just a few more bytes/cycles out of qdstart*****************************************************************	EXPORT QDStartQDStart	PROC	pha	lda >BusyFlag	inc a	sta >BusyFlag	pla	phd	; push d on stack	tcd	; set d	lda 3,s	; getorig rts	pha	; put on stack	lda 3,s	; move orig d to on	top of rts	sta 5,s	pla	; pull rts off stack	sta 1,s	; put over orig d	tdc	; get QD D back in a	rts	; done	ENDP****************************************************************** TestGPs** Internal routine to move the point to	the grafprocs to* zero page.  If this pointer is zero, then the carry* returns clear.  If the pointer is nonzero, the carry* returns set.** 15 March 89	Mensch** Shave a few more cycles out.!*****************************************************************	EXPORT TestGPsTestGPs	PROC	phx	ldy #o_grafprocs	lda [PortRef],y	tax	ldy #o_grafprocs+2	ora [PortRef],y	beq IsZero	stx temp	lda [PortRef],y	sta temp+2	sec	plx	rtsIsZero	ldx #512	lda <DirtyDPFlags,x	ora #NoUserGrafProcs	sta <DirtyDPFlags,x	plx	clc	rts	ENDP****************************************************************** PutPictStuff*****************************************************************	EXPORT iPutPictStuffiPutPictStuff	PROC	phx	ldx #512	lda <DirtyDPFlags,x	ora #NoPictRecord	sta <DirtyDPFlags,x	plx	clc	lda #0	rtl	ENDP****************************************************************** SetStdProcs     (ProcPtr : Ptr);** Sets the record containing pointers to standard procs to* point to all the standard procs in ROM.*****************************************************************	EXPORT SetStdProcsSetStdProcs	PROCRTL1	equ 1RTL2	equ RTL1+3ProcPtr	equ RTL2+3	tsc	; get stack	phd	; save direct	tcd	; set direct to stack	ldy #QDProcSize-2Loop	tyx	lda >QDProcs,x	sta [ProcPtr],y	dey	dey	bpl Loop	jmp EndCall4	ENDP******************************************************************* WideOpen** This is the default clipping region******************************************************************	EXPORT WideOpenWideOpen	PROC	DC.L TheRegion	DS.B 2	; safety for lockingTheRegion	DC.W 10	DC.W -32767/2,-32767/2,32767/2,32767/2	ENDP****************************************************************** GetAddress**            space for result   long*            id number          word******************************************************************	EXPORT GetAddressGetAddress	PROC	import ScreenTable	import ConTable320	import ConTable640RTL1	equ 1RTL2	equ RTL1+3IDNumber	equ RTL2+3ResultSpace	equ IDNumber+2	lda IDNumber,s	and #$00FF	asl a	asl a	tax	lda >MyTable-4,x	sta ResultSpace,s	lda >MyTable-4+2,x	sta ResultSpace+2,s	jmp oEndCall2MyTable		; 	DC.L ScreenTable	DC.L ConTable320	DC.L ConTable640	ENDP****************************************************************** SetSysFont** Change History** 21 Aug 86    SEG	   This forgot to phd and set tcd so zp*	   was never right.	 Moreover stack was*	   trashed on way out.*****************************************************************	EXPORT SetSysFontSetSysFont	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3FontHandle	equ RTL2+3	jsr QDStart	ldx #256	lda FontHandle,s	sta SysFont,x	lda FontHandle+2,s	sta SysFont+2,x	jmp BusyEC4	ENDP****************************************************************** GetSysFont*****************************************************************	EXPORT GetSysFontGetSysFont	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3ResultHandle	equ RTL2+3	jsr QDStart	ldx #256	lda SysFont,x	sta ResultHandle,s	lda SysFont+2,x	sta ResultHandle+2,s	jmp BusyEC0	ENDP****************************************************************** SetBufDims**        MaxWidth :	integer*        MaxFontHeight : integer*        MaxFontWidth : integer** This routine forces the resizing of all of QuickDraw's* internal buffers:	the ClipBuffer and the text buffer.** Modification History** May 9, 1986    This used to be SetMaxWidth and there separate*                text buffer sizing calls.  Since the two are*                interrelated, it is now one call.*****************************************************************	EXPORT SetBufDimsSetBufDims	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3sMaxFontWidth	equ RTL2+3sMaxFontHeight	equ sMaxFontWidth+2sMaxWidth	equ sMaxFontHeight+2	jsr QDStart	stz ForcedFont	; zero the indicator of force	EXPORT JoinBufStuffJoinBufStuff		;       	lda sMaxWidth,s	jsr CalcClipSize	pea 0	pha	pei BufferHandle+2	pei BufferHandle	_SetHandleSize	bcc noerror1AnError	tax	jmp BusyErr6noerror1	lda sMaxWidth,s	sta MaxWidth	lda sMaxFontWidth,s	sta NewMaxFontWidth	lda sMaxFontHeight,s	sta NewTBHeight	jsl SetTB	bcs AnError	lda sMaxWidth,s	sta MaxWidth	jmp BusyEC6	ENDP****************************************************************** ForceBufDims**        MaxWidth :	integer*        MaxFontHeight : integer*        MaxFontWidth : integer** This routine forces the resizing of all of QuickDraw's* internal buffers:	the ClipBuffer and the text buffer.* The text buffer sizing is done as force.** Modification History** May 9, 1986    See notes above*****************************************************************	EXPORT ForceBufDimsForceBufDims	PROC	jsr QDStart	lda #$8000	sta ForcedFont	bra JoinBufStuff	ENDP****************************************************************** SaveBufDims**     TBRecPtr    pointer** 8 bytes of information on sizing the quick draw text buffers* is moved from here to the users buffer.  This information* can restore the current state when passed back with* RestoreBufDims*****************************************************************	EXPORT SaveBufDimsSaveBufDims	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TBRecPtr	equ RTL2+3	jsr QDStart	lda TBRecPtr,s	sta temp	lda TBRecPtr+2,s	sta temp+2	lda MaxWidth	; first put the MaxWidth	sta [temp]	lda textBufHeight	; second the text buf height	ldy #2	sta [temp],y	lda textBufRowWords	; next the textBufRowWords	iny	iny	sta [temp],y	ldx #256	; finally the FontWidth from	lda FontWidth,x	; second zero page.	iny	iny	sta [temp],y	jmp BusyEC4	ENDP****************************************************************** RestoreBufDims**     TBRecPtr    pointer** Using 8 bytes of information in the record pointed to above,* QuickDraw resizes	its buffers.** The eight bytes are arranged as follows:**       MaxWidth*       TextBufHeight*       TextBufRowWords*       FontWidth*****************************************************************	EXPORT RestoreBufDimsRestoreBufDims	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3TBRecPtr	equ RTL2+3	jsr QDStart	lda TBRecPtr,s	sta temp	lda TBRecPtr+2,s	sta temp+2	lda [temp]	; using MaxWidth, calc the	jsr CalcClipSize	; right buffer size.	pea 0	; resize the handle	pha	pei BufferHandle+2	pei BufferHandle	_SetHandleSize	bcc NoError1	tax	; an error occured so quit	jmp BusyErr4NoError1		; ;----------------------------------------------------;; Now put the working MaxWidth on ZP and; resize the text buffer.;	lda [temp]	; get the MaxWidth	sta MaxWidth	ldy #2	; get the textBufHeight	lda [temp],y	sta NewTBHeight	iny	; get the textBufRowWords	iny	lda [temp],y	sta NewTBRowWords	iny	; get the FontWidth	indicator	iny	lda [temp],y	sta NewFontWidth	jsl ResetTB	; this call changes	the text buffer	bcc NoError2	; and sets the params if successful	tax	; return the error and don't	jmp BusyErr4NoError2	jmp BusyEC4	ENDPE0Vectors	PROC	ENTRY TheE0VstartTheE0Vstart		; 	jml >$000000	; toStuff	jml iStdText	jml iStdLine	jml iStdRect	jml iStdRRect	jml iStdOval	jml iStdArc	jml iStdPoly	jml iStdRgn	jml iStdPixels	jml NotImp	jml iStdTxMeas	jml iStdTxBnds	jml NotImp	jml NotImp	jml iPortLoc2ZP	jml iUserPat2ZP	jml iGetPenPReady	jml iGetBackPReady	jml iPen2ZP	jml iBack2ZP	jml iRotatePat	jml iGetMaskReady	jml iMask2ZP	jml iExpandMask	jml iRotatemask	jml iRotateLong	jml iPreDraw	jml iXSetup	jml iDrawRectB	jml iDrawRect	jml iSliceSetup		; these are not used internally!	jml ShiftStay	; because I don't want to slow		; things down.  They are provide	jml XShiftStay	; so that outside routines can use them	jml ShiftOut	jml XShiftOut	jml iBMakeMinRect	jml iMakeMinRect	jml iShieldCursor	jml iUnShieldCursor	jml iSetUpPortRegions	jml iSetUpScanPtrs	jml iFreePortRegions	jml iFree1Region	jml iFree2Regions	jml iFree3Regions		; changed 10 Mar 87	SEG (used to be	jml iGetFGS	; UnlockBufferHandle--who knows why?)	jml iInit1Region	jml iInit2Regions	jml iInit3Regions	jml iSeek1Region	jml iSeek2Regions	jml iSeek3Regions	jml iInitRgn	jml iSeekRgn	jml iJoin1Buffer	jml iJoin2Buffers	jml iJoin3Buffers	jml iSetSlabAdr	jml iSetSliceAdr	jml iSetStuffAdr	jml iBlowItUp	jml iPutPictStuff	jml iAddToPoly	jml iOpenPicture	jml iPicComment	jml iClosePicture	jml iDrawPicture	jml iKillPicture	jml iGimmeVersion	jml FrRgn	jml PRgn	jml ERgn	jml IRgn	jml FRgn	jml FrRect	jml PRect	jml ERect	jml IRect	jml FRect	jml iDChar	jml iDText	jml iBChar	jml iBText	jml iValidChar	jml iGetNextChar	jml iCalcDrawStatus	jml iTextAndMinRect	jml iCalcTextBounds	jml iSetUpFontInfo	jml iSetUpBufInfo	jml iGetTextHandle	jml iClearBufPart	jml iPutChar	jml iBumpPen	jml iCleanUpBuffer	jml iPutLine	jml iPutRgn	jml iPutRect	jml iCullPoints	jml iSortPoints	jml iPackRgn	jml iRgnOp	jml iPutOval	jml iBumpOval	jml iInitOval	jml iSetTB	jml iResetTB	jml iStyleText	jml iStyleExtents	jml iDoBold	jml iDoUnderLine	jml iStdConic	jml iDrawConic	jml iSetScaleAndMap	jml iDrawCursor	jml iUndrawCursor	jml iAngleFromSlope	jml iSlopeFromAngle	jml iRgnBlt	jml iSharedMRSetup	jml iShareShieldStuff	jml iGetCharVals	jml iDoFntFlgMods	jml iAddExtras	jml iCalcSlop	jml iGetFntInf	Entry TheE0VendTheE0VEnd	ENDP;                copy init/pictures****************************************************************** OpenPicture**       space for output   PicHandle : long*	       PicFrame  : long******************************************************************	EXPORT iOpenPictureiOpenPicture	PROC	jmp oEndCall4	ENDP****************************************************************** PicComment**       Kind     : word*       size     : word*       datahandle : handle*****************************************************************	EXPORT iPicCommentiPicComment	PROC	jmp oEndCall8	ENDP****************************************************************** ClosePicture*****************************************************************	EXPORT iClosePictureiClosePicture	PROC	jmp oEndCall0	ENDP****************************************************************** DrawPicture**            Pic	  : PicHandle*            DestRect : rectPtr  *****************************************************************	EXPORT iDrawPictureiDrawPicture	PROC	jmp oEndCall8	ENDP****************************************************************** KillPicture**        PicHandle : handle*****************************************************************	EXPORT iKillPictureiKillPicture	PROC	jmp oEndCall4	ENDP;                copy init/glue****************************************************************** NewHandleGlue** This small routine makes the new handle call in a way that* saves space.*****************************************************************	EXPORT NewHandleGlueNewHandleGlue	PROC	ldx #$0902	EXPORT ToGlueEntryToGlueEntry		;       	jsl $E10004	rtl	ENDP****************************************************************** DisposeHandleGlue** This small routine sets up the X-register and branches to* the "ToGlueEntry"	point above.*****************************************************************	EXPORT DisposeHandleGlueDisposeHandleGlue	PROC	ldx #$1002	bra ToGlueEntry	ENDP****************************************************************** CopyRgnGlue** This small routine sets up the X-register and branches to* the "ToGlueEntry"	point above.*****************************************************************	EXPORT CopyRgnGlueCopyRgnGlue	PROC	ldx #$6904	bra ToGlueEntry	ENDP****************************************************************** SetVectorGlue** This small routine sets up the X-register and branches to* the "ToGlueEntry"	point above.*****************************************************************	EXPORT SetVectorGlueSetVectorGlue	PROC	ldx #$1003	bra ToGlueEntry	ENDP****************************************************************** GetVectorGlue** This small routine sets up the X-register and branches to* the "ToGlueEntry"	point above.*****************************************************************	EXPORT GetVectorGlueGetVectorGlue	PROC	ldx #$1103	bra ToGlueEntry	ENDP******************************************************************* SpecialNewHandle** Routine to call to get new handle with**    size         passed in a-reg*    userid       passed in x-reg*    attributes   passed in y-reg** Handle is returned in X & Y register (x has low word)* unless error occurs where x & y are undifined.** For no error a-reg has 0 and carry is	clear.  If error occurs* a-reg has error and carry is set.******************************************************************	EXPORT SpecialNewHandleSpecialNewHandle	PROC	pha	; space for result	pha	pea 0	; high word of size	pha	; low word of size	phx	; id number	phy	; attributes	pha	; loc info (ignored)	pha	jsl NewHandleGlue	plx	ply	rts	ENDP	Include 'FastFontCache'	END